/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;

  const [year, month, day] = text.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));

  // Verify the parsed date matches the input (catches invalid dates like Feb 30)
  return date.getUTCFullYear() === year && date.getUTCMonth() + 1 === month && date.getUTCDate() === day;
}

/**
 * Add n days to a date (in UTC).
 * @param {string} date - date in YYYY-MM-DD format
 * @param {number} n - number of days to add
 * @returns {string} - date in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const [year, month, day] = date.split('-').map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + n);

  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const da = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${da}`;
}

/**
 * Calculate the number of whole days between two dates (b - a, in UTC).
 * @param {string} a - date in YYYY-MM-DD format
 * @param {string} b - date in YYYY-MM-DD format
 * @returns {number} - number of whole days (can be negative)
 */
export function daysBetween(a, b) {
  const [ay, am, ad] = a.split('-').map(Number);
  const [by, bm, bd] = b.split('-').map(Number);

  const dateA = new Date(Date.UTC(ay, am - 1, ad));
  const dateB = new Date(Date.UTC(by, bm - 1, bd));

  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.round(diffMs / (24 * 60 * 60 * 1000));
}

