import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

function validateDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return ok();
  if (typeof discountPercent !== 'number' || isNaN(discountPercent) || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }
  return ok();
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize and validate customer exists
  const normalizedCustomerId = normalizeId(customerId);
  const customer = getCustomer(normalizedCustomerId);
  if (!customer.ok) return customer;

  // Validate issue date format YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate each line and enrich with catalogue data
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discount: explicit value wins, otherwise use tier discount
    let discountPercent;
    if ('discountPercent' in line) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.value.tier];
    }

    // Validate discount percent
    const discountValidation = validateDiscount(discountPercent);
    if (!discountValidation.ok) return discountValidation;

    // Get product from catalogue
    const product = getProduct(line.sku);
    if (!product.ok) return product;

    const enrichedLine = {
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    };
    if (discountPercent !== undefined && discountPercent !== 0) enrichedLine.discountPercent = discountPercent;

    enrichedLines.push(enrichedLine);
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total amount for a line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(total * discountPercent / 100);
}

/**
 * Calculate the VAT amount for a line (after discount).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add a line to an invoice or increase qty if the SKU already exists.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: { status: string, lines: Array, customerId: string, issueDate: string } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer for tier discount
  const customer = getCustomer(invoice.customerId);
  if (!customer.ok) return customer;

  // Determine discount: explicit value wins, otherwise use tier discount
  let lineDiscount;
  if ('discountPercent' in arguments[1]) {
    lineDiscount = discountPercent;
  } else {
    lineDiscount = TIER_DISCOUNTS[customer.value.tier];
  }

  const discountValidation = validateDiscount(lineDiscount);
  if (!discountValidation.ok) return discountValidation;

  const product = getProduct(sku);
  if (!product.ok) return product;

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  const newLines = invoice.lines.map((line) => ({ ...line }));

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const newLine = {
      sku,
      name: product.value.name,
      qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    };
    if (lineDiscount !== undefined && lineDiscount !== 0) newLine.discountPercent = lineDiscount;
    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array, customerId: string, issueDate: string } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice by assigning it a number and changing status to issued.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, number?: string }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
    number,
  });
}

